void touchWay(int row, int way, boolean fill) {
    if (replacement.equals("LRU") || replacement.equals("FIFO") && fill)
        touched[row][way] = ++clock;
    else if (replacement.equals("PLRU")) {
        int low = 0, high = ways, node = 1;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            if (way < mid) {
                bits[row][node] = 1;
                high = mid;
                node *= 2;
            } else {
                bits[row][node] = 0;
                low = mid;
                node = 2 * node + 1;
            }
        }
    }
}
void touch(int block) {
    Location p = locate(block);
    if (p != null)
        touchWay(p.row(), p.way(), false);
}
static Request requester(String protocol, String old, String op, boolean otherHasLine) {
    if (protocol.equals("VI"))
        return op.equals("R") ? new Request(old.equals("I") ? "BusRd" : null, "V")
                              : new Request("BusWr", old.equals("I") ? "I" : "V");
    if (old.equals("I"))
        return op.equals("W")
            ? new Request("BusRdX", "M")
            : new Request("BusRd", !protocol.equals("MSI") && !otherHasLine ? "E" : "S");
    if (op.equals("R"))
        return new Request(null, old);
    return old.equals("M") || old.equals("E") ? new Request(null, "M")
                                              : new Request("BusUpgr", "M");
}
